<script lang="ts">
    import type { ComponentProps, Snippet } from "svelte";
    
    import Confetti from "../ui/Confetti.svelte";
    import SvgScene from '../ui/SvgScene.svelte';
    import AsInput from '../ui/AsInput.svelte';
    import SvgText from '../ui/SvgText.svelte';
    import AsButton from '../ui/AsButton.svelte';
    import SvgWifi from '../ui/svg/Wifi.svelte';
    import SvgPmButton from '../ui/svg/PmButton.svg.svelte';
    import ToastsBox from '../ui/ToastsBox.svelte';
    import { SvgYes } from '../ui/svg/Yes.svg.svelte';
    import { SvgNo } from '../ui/svg/No.svg.svelte';
    import { type FontName } from '../ui/excalidraw-defs'

    import { 
        logger, helpers, browser, theme, makeMain, 
    } from './cs-dependencies'

    let appId = helpers.makeId(2, "cs.");
    logger.setAppId(appId);
    let log = logger.make("console");

    let cs = makeMain(appId);
    let { toasts } = cs;

    browser.onHashChange(() => location.reload());

    let { ui, profile }  = cs;
    let { layout } = ui;

    function beforeAliasEdit() {
        log.info(_=>_(`before editing alias '${ui.name}'`));
        ui.beforeAliasEdit();
    }

    function afterAliasEdit() {
        let alias = ui.name.trim();
        if (alias === "") {
            log.info(_=>_(`removing alias ${profile.alias}`));
            cs.all.clearAlias();
            return;
        }
        if (alias === profile.alias) {
            log.info(_=>_(`same alias '${alias}'`));
            return;
        }
        log.info(_=>_(`changing '${profile.alias}'' alias to '${ui.name}''`));
        cs.all.setAliasOnEdit(ui.name);
    }

    function addProfile() {
        let name = layout.areas.find(a => a.id === "name")!;
        let hasSwitchButtons = cs.addProfile();
        name.w = hasSwitchButtons ? 58 : 80;
    }

    function area(id: string, text: string,
                  fontName: FontName) : ComponentProps<typeof SvgText>
    {
        let svg = layout.svgs.find(it => it.id === id);

        if (!svg)
            return {text, fontName};

        return {
            text,
            color: theme.map(svg.textColor),
            bgColor: theme.map(svg.bgColor),
            fontName: svg.font as FontName,
            fontScale: svg.fontScale
        }
    }

    function wifiClick() {
//        ui.hasPlusMinus = !ui.hasPlusMinus;
//        ui.layout.effectTrigger.raise();
    }

    $effect(() => cs.updateBrowserTitle());
    $effect(() => cs.sendIAmHere());
    $effect(() => cs.trackTeachers());
    $effect(() => ui.syncWithAppState());
</script>

{#snippet wifi(id: string, handler: () => void)}
    <div class="svg" {id}>
        <AsButton clicked={handler} disabled={false}>
            <SvgWifi connected={ui.connected}/>
        </AsButton>
    </div>
{/snippet}

{#snippet asButton(id: string, content: Snippet<[boolean]>, handler: () => void)}
    {@const disabled = !ui.connected}
    <div class="svg" {id}>
        <AsButton clicked={handler} {disabled}>
            {@render content(disabled)}
        </AsButton>
    </div>
{/snippet}

{#snippet text(id: string, str: string, font: FontName = "Excalifont")}
    <div class="svg" {id}>
        <SvgText {...area(id, str, font)}/>
    </div>
{/snippet}

{#snippet textBtn(id: string, str: string, handler: () => void)}
    {@const disabled = !ui.connected}
    <div class="svg" {id}>
        <AsButton clicked={handler} {disabled}>
            <SvgText {...area(id, str, "Nunito")}/>
        </AsButton>
    </div>
{/snippet}

{#snippet plusMinus(id: string, handler: () => void)}
    {#if ui.hasPlusMinus}
        {@const disabled = !ui.connected}
        <div class="svg" id="plus">
            <AsButton clicked={handler} {disabled}>
                <SvgPmButton {disabled} plus={ui.plusMinus} />
            </AsButton>
        </div>
    {/if}
{/snippet}

{#snippet switchTo(id: string, to: string, index: 1 | 2, font: FontName = "Excalifont")}
    {#if to}
        <div class="svg" {id}>
            <AsButton clicked={() => cs.switchProfileTo(index)}>
                <SvgText {...area(id, to, font)}/>
            </AsButton>
        </div>
    {/if}
{/snippet}

{#snippet student()}
    {@const id = "name"}
    <div class="svg" {id} onclick={cs.hello}>
        <AsInput bind:value={ui.name}
            beforeEdit={beforeAliasEdit}
            afterEdit={afterAliasEdit}
        >
            <SvgText {...area(id, ui.name, "Excalifont")}/>
        </AsInput>
    </div>
{/snippet}

{#snippet tag(id: string, tag: typeof ui.tag.deviceId)}
    <div bind:this={tag.html} 
        class="svg" {id} 
        onclick={() => cs.all.tagClick(id, tag.text)}
    >
        <SvgText 
            {...area(id, tag.text, "Nunito")} 
            color="gray" borderColor="gray" bgColor="white"
        />
    </div>
{/snippet}

<div class="console">
    <SvgScene {layout}>
        <div class="section" id="header">
            {@render wifi("wifi", wifiClick)}
            {@render student()}
            {@render switchTo("switch", ui.switchTo, 1)}
            {@render switchTo("switch-2", ui.switchTo2, 2)}
            {@render plusMinus("plus", addProfile)}
            {@render text("group", ui.group)}
        </div>

        <div class="section" id="pad">
            <Confetti bind:this={ui.confetti} />
            {@render asButton("yes", SvgYes, cs.yes)}
            {@render asButton("no", SvgNo, cs.no)}
            <ToastsBox daisyUi="toast-top toast-end" toasts={toasts.all}/>
        </div>

        <div class="section" id="footer">
            {@render tag("device-id", ui.tag.deviceId)}
            {@render tag("profile", ui.tag.profile)}
            {@render tag("version", ui.tag.version)}
            {@render tag("alias", ui.tag.codename)}
            {@render tag("classroom", ui.tag.classroom)}
            {@render tag("status", ui.tag.status)}
        </div>
    </SvgScene>


</div>

<style>
    .console {
        min-height: 100dvh;
        background-color: pink;
    }

    .section {
        position: relative;
    }

    .svg {
        position: absolute;
        overflow-y: visible;
    }
</style>
