import { initializeApp } from "firebase/app";
import { getDatabase, ref, onValue, runTransaction } from "firebase/database";


import { logger } from './logger.svelte'

interface Firebase {
    makeSharedCounter(id: string): {
        get value(): number;
        increment(): void;
        decrement(): void;
    }
}

export type SharedCounter = ReturnType<Firebase["makeSharedCounter"]>

const firebaseConfig = {
    apiKey: "AIzaSyD1T1d6L2qF2bDjHxIQaidyuKIlNPxikK0",
    authDomain: "gebemot-enrolment-v0.firebaseapp.com",
    databaseURL: "https://gebemot-enrolment-v0-default-rtdb.europe-west1.firebasedatabase.app",
    projectId: "gebemot-enrolment-v0",
    storageBucket: "gebemot-enrolment-v0.firebasestorage.app",
    messagingSenderId: "677976152796",
    appId: "1:677976152796:web:6bf19a46934ff18ff8b219"
};

export function makeFirebase() {
    let log = logger.make("firebase");
    let app = initializeApp(firebaseConfig);
    let database = getDatabase(app);

    function makeSharedCounter(id: string) {

        let value = $state(0);
        let domain = location.hostname.replaceAll('.', '-');

        let path = `shared/${domain}_${id}/counter`;
        let counterRef = ref(database, path);

        onValue(counterRef, snapshot => {
            let x = snapshot.val() ?? 0;
            value = x;
            log.info(_=>_({id, value: x}));
        });        

        log.info(_=>_({id, path}));

        async function increment() {
            await runTransaction(counterRef, x => x + 1);            
            log.info(_=>_({id}));
        }

        async function decrement() {
            await runTransaction(counterRef, x => x - 1);            
            log.info(_=>_({id}));
        }

        return {
            get value() { return value; },
            increment,
            decrement,
        } satisfies SharedCounter;
    }

    return {
        makeSharedCounter,
    } satisfies Firebase;
}