<script lang="ts">
    import { onMount } from "svelte";
    import { browser } from '../tch/tch-dependencies'

    interface Props {
        baseUrl?: string;
        classroom?: string;
        size?: number;
    }

    type QrCodeOptions = {
        text: string;
        width: number;
        height: number;
        colorDark: string;
        colorLight: string;
        correctLevel: number;
    }

    type QrCodeInstance = {
        clear(): void;
        makeCode(text: string): void;
    }

    type QrCodeConstructor = {
        new (element: HTMLElement, options: QrCodeOptions): QrCodeInstance;
        CorrectLevel: {
            M: number;
        };
    }

    type WindowWithQrCode = Window & typeof globalThis & {
        QRCode?: QrCodeConstructor;
    }

    let {
        baseUrl = "gebemot.online",
        classroom = "112233",
        size = 200
    }: Props = $props();

    const qrCodeUrl = "https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js";

    let target: HTMLDivElement;
    let libraryReady = $state(false);
    let qrCode: QrCodeInstance | undefined;
    let renderedSize = 0;

    const encodedUrl = $derived(`${baseUrl}/${classroom}`);

    onMount(() => {
        if (getQrCode()) {
            libraryReady = true;
            return;
        }

        const existingScript = document.querySelector<HTMLScriptElement>(`script[src="${qrCodeUrl}"]`);
        const handleLoad = () => {
            libraryReady = true;
        };

        if (existingScript) {
            existingScript.addEventListener("load", handleLoad, { once: true });

            return () => {
                existingScript.removeEventListener("load", handleLoad);
            };
        }

        const script = document.createElement("script");

        script.src = qrCodeUrl;
        script.crossOrigin = "anonymous";
        script.referrerPolicy = "no-referrer";
        script.addEventListener("load", handleLoad, { once: true });

        document.head.append(script);

        return () => {
            script.removeEventListener("load", handleLoad);
        };
    });

    $effect(() => {
        const QRCode = getQrCode();

        if (!target || !libraryReady || !QRCode) {
            return;
        }

        if (!encodedUrl) {
            target.replaceChildren();
            qrCode = undefined;
            renderedSize = 0;
            return;
        }

        if (!qrCode || renderedSize !== size) {
            target.replaceChildren();
            qrCode = new QRCode(target, {
                text: encodedUrl,
                width: size,
                height: size,
                colorDark: "#000000",
                colorLight: "#ffffff",
                correctLevel: QRCode.CorrectLevel.M
            });
            renderedSize = size;

            return;
        }

        qrCode.clear();
        qrCode.makeCode(encodedUrl);
    });

    function addParam(params: URLSearchParams, name: string, value: string) {
        const trimmedValue = value.trim();

        if (trimmedValue !== "") {
            params.set(name, trimmedValue);
        }
    }

    function getQrCode() {
        return (window as WindowWithQrCode).QRCode;
    }

    function qrCodeClick() {
        browser.copyToClipboard(encodedUrl);
    }
</script>

<div
    class="qr-code"
    bind:this={target}
    onclick={qrCodeClick}
    aria-label="Generated QR code"
    style:width={`${size}px`}
    style:height={`${size}px`}
></div>
<div>
    <a href={encodedUrl} title="">{encodedUrl}</a>
</div>

<style>
    .qr-code {
        display: grid;
        place-items: center;
    }
</style>
