import { mount, type Component } from 'svelte'
import { config } from './misc/config.svelte'
import { VERSION } from './version'
import Console from './cs/Console.svelte'
import Cockpit from './tch/ui/Cockpit.svelte'
import School from './sch/School.svelte'

let site = new Map<string, Component<any>>([
    ["gebemot.online", Console],
    ["gebemot.io", Cockpit],
    ["gebemot.school", School],
    ["localhost", Console],
    ["tch", Cockpit],
    ["sch", School],
]);

let domain = location.hostname;
console.log(`Gebemot ${VERSION}: ${domain}`);

let page = 
    site.get(config.app) ?? 
    site.get(domain) ?? 
    Console;

mount(page, { target: document.getElementById("app")! });
