import type {IAmATeacher, CsAbly, Browser } from './tch-dependencies'
import { logger, helpers, config } from './tch-dependencies'

export interface IAmHere {
    send(): void;
}

export function makeIAmHere(
    appId: string, 
    browser: Browser,
    ably: CsAbly,
) {
    let log = logger.make("presence");

    let itsAMobile = browser.itsLikelyAMobile();
    let iAmHereTrigger = helpers.makeEffectTrigger();
    let hostId = $state(1);

    browser.onBackFromCache(() => iAmHereTrigger.raise());

    function send() {
        iAmHereTrigger.registerDependency();

        let iAmATeacher: IAmATeacher = {
            role: "teacher",
            deviceId: config.deviceId,
            appId: appId,
            itsAMobile,
            auth: {
                token: "alkjiowjkl-fdew=faerw+-",
                username: "Gosha Smeh",
                email: "gosha.smeh@gmail.com"
            },
            hostId,
        };

        ably.present(iAmATeacher);

        log.info(_=>_(iAmATeacher));
    }

    return {
        send,
    } satisfies IAmHere;
}