import type { } from './tch-dependencies'
import { logger, helpers } from './tch-dependencies'

type StudentPresence = "absent" | "out-of-focus" | "hello-is-missing" | "here";

export interface Peer {
    deviceId: string;
    appId: string;
    profileId: string;
    codename: string;
    alias: string;
    isActive: boolean;
}

export interface Student {
    get name(): string;
    get isActive(): boolean;
    get presence(): StudentPresence;
    get mobileIsHere(): boolean;
    online: {
        peers: Peer[];
        appIsVisible: boolean;
        appIsFocused: boolean;
        helloIsHere: boolean;
        mobileIsHere: boolean;
    };
    studying: {
        grade: number;
        answer: string;
    }
    classroom: {
        name: string;
        lastSeenName: string;
        grade: number;
    };
}

export type OnlinePeer = Student["online"];

export function makeOnlinePeer(): OnlinePeer {
    return {
        peers: [],
        appIsFocused: false,
        appIsVisible: false,
        helloIsHere: false,
        mobileIsHere: false,
    }
}

export function makeStudent(id: string): Student {
    let stu = helpers.reactive({
        get name() { return name; },
        get isActive() { return isActive; },
        get presence() { return presence; },
        get mobileIsHere() { return mobileIsHere; },
        online: makeOnlinePeer(),
        studying: {
            grade: 0,
            answer: "",
        },
        classroom: {
            name: "",
            lastSeenName: "",
            grade: 0,
        }
    } as Student);

    let name = $derived.by(() => {
        if (stu.classroom.name) return stu.classroom.name;
        let peers = stu.online.peers;
        if (peers.length === 0) return stu.classroom.lastSeenName;
        return peers[0].alias || peers[0].codename;  
    });

    let isActive = $derived.by(() =>
        stu.online.appIsVisible && 
        stu.online.appIsFocused
    );

    let presence = $derived.by((): StudentPresence => {
        let online = stu.online;

        if (online.peers.length === 0)
            return "absent";

        let isActive = 
            online.appIsFocused && 
            online.appIsVisible;

        if (isActive)
            return online.helloIsHere ? "here" : "hello-is-missing";

        return "out-of-focus";
    });

    let mobileIsHere = $derived.by(
        () => stu.online.mobileIsHere
    );

    return stu;
}

