<script lang="ts">
  import ToastsBox from '../ui/ToastsBox.svelte';
    import { 
        logger, helpers, makeAbly, browser, makeSchedule,
        makeMain,
        VERSION
    } from './sch-dependencies'

    import type {
        SchCourse, SchLesson, SchSession 
    } from './sch-dependencies'

    let schedule = makeSchedule();

    browser.setPageTitle(`Gebemot school ${VERSION}`);

    let appId = helpers.makeId(2, "sch.");
    logger.setAppId(appId);
    let log = logger.make("sch-main");

    let sch = makeMain(appId)
    let { toasts } = sch;
</script>

{#snippet Course(course: SchCourse)}
    {@const lesson = course.lessons[0]}
    {@const session = lesson.sessions[0]}
    {@const tailwind = lesson.tailwind}
    {@const counter = sch.getSharedCounter(course, lesson, session)}
    <div class="row {tailwind}">
        <span class="kbd">{course.name}</span>
        <span class="kbd">{lesson.topic}</span>
        <span class="kbd">{session.date}</span>
        <span class="kbd">{session.time}</span>

        <div class="iAmIn">
            <input type="checkbox"
                class="toggle toggle-sm checked:bg-orange-400" 
                bind:checked={
                    () => sch.getEnrollment(course, lesson, session),
                    yes => sch.enroll(course, lesson, session, yes)
                }
            />
            <span>באים</span>
        </div>

        <span class="kbd">
            {counter.value}
        </span>
    </div>
{/snippet}


<div class="rows flex w-full flex-col">
    {#each schedule.courses as course}
        {@render Course(course)}
    {/each}
    <ToastsBox daisyUi="toast-bottom toast-end" toasts={toasts.all}/>
</div>


<style>
.rows {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-evenly;
    align-items: center;
    width: 100%;
    gap: 10px 0;
}
.row {
    width: 100%;
    height: 100%;
}
.rows > * {
    display: inline;
}
.iAmIn {
    display: inline;
}
</style>