import firebase from 'firebase/compat/app';
import type { 
    CsToasts,
    SchCourse, SchLesson, SchSession, SharedCounter, 
} from './sch-dependencies';

import {
    config, logger, browser, makeToasts,
    makeFirebase,
    helpers,
} from './sch-dependencies'

interface SchMain {
    toasts: CsToasts;
    getSharedCounter(course: SchCourse, lesson: SchLesson, session: SchSession): SharedCounter;
    enroll(course: SchCourse, lesson: SchLesson, session: SchSession, yes: boolean): void;
    getEnrollment(course: SchCourse, lesson: SchLesson, session: SchSession): boolean;
}

export function makeMain(appId: string) {
    let log = logger.make("cs-main");

    log.info(_=>_({
        appId, 
        deviceId: config.deviceId,
        config,
    }));

    let firebase = makeFirebase();
    let toasts = makeToasts();

    function makeId(course: SchCourse, lesson: SchLesson, session: SchSession) {
        let courseId = course.id;
        let lessonId = lesson.id;
        let date = session.date.replaceAll('/', '-');
        let time = session.time.replaceAll(':', '-');
        return `${courseId}_${lessonId}_${date}_${time}`;
    }

    let counters = new Map<string, SharedCounter>();

    function getSharedCounter(
        course: SchCourse,
        lesson: SchLesson,
        session: SchSession
    ) {
        let id = makeId(course, lesson, session);
        log.info(_=>_({id}));

        let counter = helpers.getOrInsert(counters, id,
            () => firebase.makeSharedCounter(id));

        return counter;
    }

    function enroll(
        course: SchCourse,
        lesson: SchLesson,
        session: SchSession,
        yes: boolean
    ) {
        let id = makeId(course, lesson, session);
        log.info(_=>_({id}));

        localStorage.setItem(id, yes.toString());
        let counter = getSharedCounter(course, lesson, session);

        switch (yes) {
            case true:
                counter.increment();
                toasts.success("יופי, נתראה בשיעור");
                break;
            case false:
                counter.decrement();
                toasts.warning("אולי בפעם הבאה");
                break;
        }
    }

    function getEnrollment(
        course: SchCourse,
        lesson: SchLesson,
        session: SchSession
    ) {
        let id = makeId(course, lesson, session);

        let yes = helpers.getCached(id, () => false);
        log.info(_=>_({id, yes}));

        return yes;
    }

    return {
        toasts,
        getSharedCounter,
        enroll,
        getEnrollment,
    } satisfies SchMain;
}