<script lang="ts">
    import { type FontName } from './excalidraw-defs'

    interface Props {
        text: string;
        color?: string;
        bgColor?: string;
        borderColor?: string;
        fontName?: FontName;
        fontScale?: number;
    }

    let {
        text,
        color = "blue",
        bgColor = "#e7f5ff",
        borderColor = "#1e1e1e",
        fontName = "Excalifont",
        fontScale = 1.0,
    }: Props = $props();

    const CX = 660;
    const CY = 100;
    const FONT_SIZE = 52;

    let width = $state(CX);
    let height = $state(CY);

    let sx = $derived(width / CX);
    let sy = $derived(height / CY);
    let fontSize = $derived(FONT_SIZE * sy * fontScale);
    let clipped = $derived(clipText(text, fontSize, width));

    function scale(str: string): string {
        let index = 0;
        return str.replace(
            /[-+]?(?:\d+\.?\d*|\.\d+)(?:e[-+]?\d+)?/gi,
            value => {
                const factor = index++ % 2 === 0 ? sx : sy;
                return String(Number((Number(value) * factor).toPrecision(15)));
            }
        );
    }

    function clipText(text: string, fontSize: number, width: number) {
        let clipped = text;
        let canvas = document.createElement("canvas");
        let context2d = canvas.getContext("2d")!;
        context2d.font = `${fontSize}px '${fontName}'`;
        while (context2d.measureText(clipped).width > width-50*sx) {
            clipped = clipped.slice(0, -1);
        }
        return clipped;
    }
</script>

<svg version="1.1"
    bind:clientWidth={width} bind:clientHeight={height}
    viewBox="0 0 {width} {height}"
    width="100%" height="100%"
>
    <!--rect x="0" y="0" {width} {height} fill="white"></rect-->
    <g stroke-linecap="round" transform={scale("translate(10 10)")}>
        <path
            d="{scale(`
                M20 0 
                C232.57     2.2,    446.77  -1.73,  620 0 
                C635.44     0.63,   635.84  2.3,    640 20 
                C634.1      31.27,  641.65  44.86,  640 60 
                C645.16     68.32,  628.65  77.18,  620 80 
                C487.69     79.61,  355.09  78.6,   20  80 
                C9.6        83.46,  -0.12   74.04,  0   60 
                C-2.58      47.19,  -4.22   40.31,  0   20 
                C4.15       2.26,   2.88    -5.27,  20  0
            `)}"
            stroke="none" stroke-width="0" fill={bgColor}>
        </path>
        <path
            d="{scale(`
                M20  0  C215.68 1.05, 412.27 -0.8, 620 0 
                M20  0  C211.99 1.65, 403.04 1.5, 620 0 
                M620 0  C636.04 3.12, 637.4 3.08, 640 20 
                M620 0  C633.31 -0.29, 636.99 5.53, 640 20 
                M640 20 C643.07 31.13, 638.83 42.69, 640 60 
                M640 20 C638.72 34.69, 640.14 46.44, 640 60 
                M640 60 C642.07 69.35, 633.28 78.48, 620 80 
                M640 60 C642.07 74.99, 635.03 83.9, 620 80 
                M620 80 C424.77 75.2, 229.38 74.38, 20 80 
                M620 80 C442.51 80.79, 265.43 80.96, 20 80 
                M20  80 C7.26 79.89, 1.61 74.51, 0 60 
                M20  80 C9.14 83.58, 4.18 75.83, 0 60 
                M0   60 C0.38 47.36, 1.77 39.2, 0 20 
                M0   60 C1.37 47.25, -1.09 36.15, 0 20 
                M0   20 C0.23 4.24, 3.66 -2.28, 20 0 
                M0   20 C-0.94 10.69, 2.55 -1.43, 20 0
            `)}"
            stroke={borderColor} stroke-width="{4*sy}" fill="none">
        </path>
    </g>
    <g transform="translate({Math.min(30, 30*sx)} {62*sy})">
        <text x="0" y="0"
            font-family={fontName} 
            font-size={fontSize} 
            fill={color}
            text-anchor="start"
            style="white-space: pre;" 
            direction="ltr" 
            dominant-baseline="alphabetic"
        >
            {clipped}
        </text>
    </g>
</svg>
