import type { Logger } from './logger.svelte'

export function assert(expr: () => boolean, log?: Logger) {
    if (expr()) return;

    let msg = `ASSERT has failed: ${expr.name}`;

    if (!log)
        console.error(msg, expr);

    log?.error(_=>_(msg, expr));

    throw new Error(msg);
}

export function warn_if(expr: () => boolean, log: Logger) {
    if (!expr()) return;

    let msg = `warning: ${expr.name}`;

    if (log)
        log.warn(_=>_(msg, expr));
    else
        console.warn(msg, expr);
}
