import { logger } from "./logger.svelte";
import { helpers } from "./helpers.svelte";

export type MyConfig = typeof config;

interface UrlArgs extends Record<string, string | boolean> {
    app: string;
    classroom: string;
    key: string;
    btnClearCache: boolean;
}

interface CsConfig {
    app: string;
    classroom: string;
    key: string;
    btnClearCache: boolean;
    deviceId: string;
    codenames: string[];
    clearLocals(): void;
}

export const config = (() => {
    let log = logger.make("config");

    let locals = helpers.getCached("console-locals", () => ({
        deviceId: helpers.makeId(4),
        codenames: [
            helpers.makeCodename(),
            helpers.makeCodename(),
            helpers.makeCodename()
        ]
    }));

    function parseHashArgs(args: UrlArgs) {
        let hash = location.hash;
        if (!hash) return;

        let segments = hash.split("/");

        if (segments.length === 1) {
            args.classroom = segments[0].replaceAll("#", "");
            return;
        }

        args.classroom = segments[1];
    }

    function toVarName(name: string): string {
        let result = name.replace(
            /[-_]+(.)?/g,
            (_, char: string | undefined) => char?.toUpperCase() ?? ""
        );
        return result.charAt(0).toLowerCase() + result.slice(1);
    }

    function parseUrlPath(args: UrlArgs) {
        let segments = window.location.pathname
            .split("/")
            .filter(segment => segment !== "")
            .map(decodeURIComponent);

        if (segments.length === 0)
            return;

        if (segments.length === 1) {
            args.classroom = segments[0].trim();
            return;
        }

        for (let i = 0; i < segments.length - 1; i++) {
            args[toVarName(segments[i])] = segments[i + 1];
        }
    }

    function parseUrlArgs(args: UrlArgs) {
        for (let [name, strValue] of new URLSearchParams(window.location.search)) {
            let value = strValue === "" ? true : strValue;
            args[toVarName(name)] = value;
        }
    }

    function clearLocals() {
        localStorage.clear();
    }

    let args: UrlArgs = {
        app: "console",
        classroom: "112233",
        key: "-4ftTQ.1tGBgQ:knDkgiTP0i4HlHBD1lE0SA5dK9w2tBk-3bf3Bi8aXXc",
        btnClearCache: false,
    };

    parseUrlPath(args);
    parseUrlArgs(args);
    parseHashArgs(args);

    return {
        ...locals,
        ...args,
        clearLocals,
    } satisfies CsConfig;
})();
