<script lang="ts">
    interface Props {
        connected: boolean;
        yesColor?: string;
        noColor?: string
    }

    let {
        connected,
        yesColor = "green",
        noColor = "gray"
    }: Props = $props();

    let active = $state(0);

    function sgColor(no: number) {
        if (connected)
            return yesColor;
        if (active === -1)
            return noColor;
        if (no === 0)
            return yesColor;
        if (no === active)
            return yesColor;
        return noColor;
    }

    let timing2 = [
        [0, 500],
        [-1, 200],
        [0, 200],
        [-1, 200],
        [0, 200],
        [1, 300],
        [2, 300],
        [3, 300],
        [0, 300],
    ];

    function blink(next: number) {
        next %= timing2.length;
        active = timing2[next][0];
        setTimeout(() => blink(next+1), timing2[next][1]);
    }

    $effect(() => {
        setTimeout(() => blink(0), 200);
    });
</script>

