<script lang="ts">
    import SvgText from "../../ui/SvgText.svelte"
    import AsInput from '../../ui/AsInput.svelte'
    import JoinToolbar from './JoinToolbar.svelte'
    import IconToolbar from './IconToolbar.svelte'
    import StudentName from './StudentName.svelte'
    import Peers from './Peers.svelte'

    import type { ClassroomUi, StudentUi } from '../tch-dependencies'    
    import { } from '../tch-dependencies'

    interface Props {
        ui: ClassroomUi;
        stu: StudentUi;
    }

    let { ui, stu }: Props = $props();

    function beforeAliasEdit(stu: StudentUi) {
        if (stu.label.text === stu.label.text) {
            stu.label.text = ""
        }
    }

    function afterAliasEdit(stu: StudentUi) {
        if (stu.label.text.trim() === "") {
            stu.label.text = stu.label.text;
            ui.clearAlias(stu);
        } else {
            ui.updateAlias(stu, stu.label.text);
        }
    }

    let syncCount = 0;

    $effect(() => ui.syncStudent(stu, ++syncCount));
</script>

{#snippet answer(stu: StudentUi)}
    {#if stu.answer.text}
        {@const {text, color, bgColor} = stu.answer}
        <span class="kbd answer-text"
            style:--color={color}
            style:--bgColor={bgColor}
        >
            {text}
        </span>
    {/if}
{/snippet}

{#snippet btnPointsGain(stu: StudentUi)}
    {@const {gain, text} = stu.points}
    <button class="btn btn-xs points-gain"
        onclick={() => ui.gainPoints(stu, gain)}
    >
        {text}
    </button>
{/snippet}

{#snippet btnClearCache(stu: StudentUi)}
    {#if stu.clearCache}
        <button class="btn btn-xs btn-active btn-warning clear-cache"
            onclick={() => ui.clearCache(stu)}
        >
            Clear cache
        </button>
    {/if}
{/snippet}

{#snippet status(stu: StudentUi)}
    {@const status = stu.status}
    {#if status}
        <kbd class="kbd kbd-sm bg-blue-50">{stu.status}</kbd>
    {/if}
{/snippet}

<div class="student card card-border shadow-sm">
    <div class="name-area" style:grid-area="name-area">
        <div class="name-edit" style:grid-area="name-edit"
            onclick={() => ui.congrats(stu)}
        >
            <AsInput bind:value={stu.label.text}
                beforeEdit={() => beforeAliasEdit(stu)}
                afterEdit={() => afterAliasEdit(stu)}
            >
                {@const {text, color, bgColor} = stu.label}
                <SvgText {text} color={color} {bgColor} />
            </AsInput>
        </div>
        <div class="name-toolbar" style:grid-area="name-toolbar">
            <IconToolbar {stu} />
        </div>
    </div>
    <div class="controls-area" style:grid-area="controls-area">
        <StudentName {stu} />
        {@render status(stu)}
        {@render btnPointsGain(stu)}
        {@render btnClearCache(stu)}
        <Peers {stu} />
    </div>
    <div class="answer-area" style:grid-area="answer-area">
        {@render answer(stu)}
    </div>
</div>

<style>
    /*-----------------------------------------------*/    
    /*-----------------------------------------------*/    
    /*- student ----------------------------------------------*/    
    .student {
        height: 120px;
        display: grid;
        grid-template-rows: 50% 25% 25%;
        grid-template-areas:
            "name-area"
            "controls-area"
            "answer-area";
    }
    /*-----------------------------------------------*/    
    .name-area {
        display: grid;
        grid-template: 1fr / 90% 10%;
        grid-template-areas:
            "name-edit name-toolbar"
    }
    .name-edit {
        height: 100%;
    }
    .name-toolbar {
        width: 100%;
        height: 100%;
    }
    /*-----------------------------------------------*/    
    .controls-area {
        display: flex;
        justify-content: left;
        padding-left: 5px;
        padding-right: 5px;
        gap: 10px;
    }
    /*-----------------------------------------------*/    
    .answer-area {
        padding-left: 5px;
    }

    /*-----------------------------------------------*/    
    .btn {
        flex: 0 0 80px;
    }
    .points-gain {
        flex: 0 0 auto;
        width: fit-content;
    }
    .clear-cache {
        margin-left: auto;
    }
    .answer-text {
        color: var(--color);
        background-color: var(--bgColor);
        font-weight: bold;
    }
</style>
