import { makeCodename } from "./codename-generator"; 
import { getCached } from "./get-cached";

export type Partial2<T> = {
    [P in keyof T]?:
        T[P] extends object ? Partial2<T[P]> : T[P];
}

export type AllThere<T> = NonNullable<Required<T>>;

export type Arg0<T extends (...args: any[]) => any> = Parameters<T>[0];
export type EffectTrigger = ReturnType<Helpers["makeEffectTrigger"]>;

interface Helpers {
    getFileName(path: string): string | undefined;
    getFileNameWithoutExtension(path: string): string;
    makeId(noOfSegments: number, prefix?: string): string;
    makeCodename: typeof makeCodename;
    getCached: typeof getCached;
    assign<U extends object>(value: U, props: Partial<U>): void;
    deepAssign<T extends object>(target: T, src: Partial2<T>): void;
    reactive<T>(value: T): T;
    derived<T>(calculate: () => T): T;
    makeEvent<Args extends unknown[]>(): {
        add(handler: (...args: Args) => void): void;
        fire(...args: Args): void;
        isEmpty(): boolean;
    };
    makeEffectTrigger(): {
        registerDependency(): void;
        raise(): void;
    };
    applyDefaults<T extends object>(options: T | undefined, defaults: AllThere<T>): AllThere<T>;
    getOrInsert<T extends object>(map: Map<string, T>, key: string, make: () => T): T;
}

export const helpers = (() => {
    function getFileName(path: string) {
        return path.replaceAll('\\', '/').split('/').pop();
    }

    function getFileNameWithoutExtension(path: string) {
        return path.replaceAll('\\', '/').split('/').pop()!.split('.')[0];
    }

    function makeId(noOfSegments: number, prefix = "") {
        let diggits = "0123456789";
        let letters = "abcdefghijklmnopqrstuvwxyz";
        let segments: string[] = [];
        let count = 0;
        
        let dgt = () => diggits.charAt(Math.floor(Math.random() * diggits.length));
        let ltr = () => letters.charAt(Math.floor(Math.random() * letters.length));

        while (count++ < noOfSegments) {
            segments.push(count % 2 === 0 ?
                `${dgt()}${dgt()}` : `${ltr()}${ltr()}`);
        }

        let id = segments.join('.');

        return prefix ? `${prefix}${id}` : id;
    }

    function assign<U extends object>(value: U, props: Partial<U>) {
        Object.assign(value, props)
    }

    function deepAssign(target: any, src: any) {
        for (let key of Object.keys(src)) {
            let sourceValue = src[key];
            let targetValue = target[key];

            if (Array.isArray(sourceValue)) {
                if (targetValue === null || targetValue === undefined) {
                    targetValue = [];
                    target[key] = targetValue;
                }
                else if (!Array.isArray(targetValue)) {
                    throw new TypeError(`Target property "${key}" is not an array`);
                }

                targetValue.splice(0, targetValue.length, ...sourceValue);
            }
            else if (sourceValue !== null && typeof sourceValue === "object") {
                if (targetValue === null || targetValue === undefined) {
                    targetValue = {};
                    target[key] = targetValue;
                }
                else if (typeof targetValue !== "object" || Array.isArray(targetValue)) {
                    throw new TypeError(`Target property "${key}" is not an object`);
                }

                deepAssign(targetValue, sourceValue);
            }
            else {
                target[key] = sourceValue;
            }
        }

        return target;
    } 

    function reactive<T>(value: T): T {
        let state = $state(value);
        return state;
    }

    function derived<T>(calculate: () => T): T {
        let value = $derived.by(calculate);
        return (() => value)();
    }

    function makeEvent() {
        let handlers: ((...args: any[]) => void)[] = [];

        function add(handler: (...args: any[]) => void) {
            if (handlers.find(func => func === handler))
                return;
            handlers.push(handler);
        }

        function fire(...args: any[]) {
            handlers.forEach(handler => handler(...args));
        }

        return {
            add,
            fire,
            isEmpty: () => handlers.length === 0,
        }
    }

    function makeEffectTrigger() {
        let state = $state(0);
        let counter = 0;
        return {
            registerDependency: () => counter = state >= 0 ? counter+1 : 0,
            raise: () => state = counter,
        }
    }

    function applyDefaults<T extends object>(
        options: T | undefined, 
        defaults: AllThere<T>): AllThere<T>
    {
        return {
            ... defaults,
            ... options ? options : {}
        }
    }

    function getOrInsert<T extends object>(
        map: Map<string, T>,
        key: string, 
        make: () => T): T 
    {
        let value = map.get(key);
        if (value) return value;

        value = make();
        map.set(key, value);

        return value;
    }

    return {
        getFileName,
        getFileNameWithoutExtension,
        makeId,
        makeCodename,
        getCached,
        assign,
        deepAssign,
        reactive,
        derived,
        makeEvent: makeEvent as Helpers["makeEvent"],
        makeEffectTrigger,
        applyDefaults,
        getOrInsert,
    } as const satisfies Helpers;
})();
