import { VERSION } from '../version'
import Confetti from "./../ui/Confetti.svelte";
import { type FontName } from '../ui/excalidraw-defs'

import { As, helpers, theme, logger } from './cs-dependencies'

import type { 
    Partial2,  EffectTrigger, CsConfig, CsProfile
} from './cs-dependencies'

import { animatePoints, gainPreset } from '../ui/gain-points-animation'

interface Tag {
    text: string;
    html: HTMLElement | null;
}

interface Ui {
    name: string;
    switchTo: string;
    switchTo2: string;
    group: string;
    connected: boolean;
    plusMinus: boolean;
    hasPlusMinus: boolean;
    confetti: Confetti | null;
    tag: {
        deviceId: Tag;
        profile: Tag;
        version: Tag;
        codename: Tag;
        classroom: Tag;
        status: Tag;
    };
}

interface Layout {
    sections: {
        id: string;
        h: number;
        color: string;
    }[];
    areas: {
        id: string;
        l: number;
        t: number;
        w: number;
        h: number;
    }[];
    svgs: {
        id: string;
        textColor?: string;
        bgColor?: string;
        font?: FontName;
        fontScale?: number;
    }[];
    effectTrigger: EffectTrigger;
}

interface CsUi extends Ui {
    layout: Layout;
    syncWithAppState(): void;
    beforeAliasEdit(): void;
    setAlias(alias: string): void;
    hello(): void;
    congrats(): void;
    gainPoints(points: number): void;
}

export function makeUi(appId: string, 
    profile: CsProfile, config: CsConfig) 
{
    let log = logger.make("ui");

    let empty = () => ({
        text: "", 
        html: null as HTMLElement | null,
    });

    let state = $state({
        name: "",
        switchTo: "",
        switchTo2: "",
        group: "",
        connected: false as boolean,
        plusMinus: true as boolean,
        hasPlusMinus: false as boolean,
        confetti: null as Confetti | null,
        tag: {
            deviceId: empty(),
            profile: empty(),
            version: empty(),
            codename: empty(),
            classroom: empty(),
            status: empty(),
        },
    } satisfies Ui);

    let layout: Layout = $state({
        sections: [
            { id: "header", h: 30, color: "antiquewhite" },
            { id: "pad",    h: 60, color: "beige" },
            { id: "footer", h: 10, color: "antiquewhite" }
        ],
        areas: [
            { id: "wifi",   l: 90, t: 2,  w: 10, h: 20 },
            { id: "name",   l: 5,  t: 9,  w: 80, h: 30 },
            { id: "switch",   l: 65,  t: 12, w: 25, h: 12 },
            { id: "switch-2", l: 65,  t: 24, w: 25, h: 12 },
            { id: "plus",   l: 89.5, t: 22, w: 10, h: 20 },
            { id: "group",  l: 40, t: 45, w: 50, h: 20 },

            { id: "yes", l: 7,  t: 12, w: 40, h: 30 },
            { id: "no",  l: 52, t: 56, w: 40, h: 30 },

            { id: "device-id",  l: 2,  t: 5,  w: 25, h: 30 },
            { id: "profile",    l: 2,  t: 35, w: 25, h: 30 },
            { id: "version",    l: 2,  t: 65, w: 25, h: 30 },
            { id: "alias",      l: 32, t: 5,  w: 25, h: 30 },
            { id: "classroom",  l: 32, t: 35, w: 25, h: 30 },
            { id: "status",     l: 32, t: 65, w: 25, h: 30 },
        ],
        svgs: [
            { id: "name", bgColor: "#ffec99", fontScale: 1.1, font: "Excalifont" },
            { id: "switch", bgColor: "#ffec99", fontScale: 1.0, font: "Nunito" },
            { id: "switch-2", bgColor: "#ffec99", fontScale: 1.0, font: "Nunito" },
            { id: "group", font: "Nunito" },
        ],
        effectTrigger: helpers.makeEffectTrigger(),
    } satisfies Layout);

    function syncWithAppState() {
        let profiles = profile.activeProfiles;

        let name = profiles[0].alias;
        let switchTo = profiles.length > 1 ? profiles[1].alias : "";
        let switchTo2 = profiles.length > 2 ? profiles[2].alias : "";

        let update = {
            name, switchTo, switchTo2,
            group: "2-19",
            plusMinus: true,
            hasPlusMinus: false,
            tag: {
                deviceId: {text: config.deviceId},
                profile: {text: appId},
                version: {text: VERSION},
                codename: {text: profile.codename},
                classroom: {text: config.classroom},
                status: {text: "OK"},
            }
        } satisfies Partial2<Ui>;

        // name is bounded to input component, thus updating it
        // causes internal read which registeres it as an effect dependency
        queueMicrotask(() => {
            helpers.deepAssign(state, update);
        });
    }

    function beforeAliasEdit() {
        if (state.name === profile.codename) {
            state.name = ""
        }
    }

    function setAlias(alias: string) {
        state.name = alias;
    }

    function hello() {
        let name = layout.svgs.find(it => it.id === "name")!;
        let hello = layout.svgs.find(it => it.id === "hello")!;

        name.bgColor = theme.map("bg-green-100"); // "#ebfbee";
    }

    function congrats() {
        state.confetti?.launch();
    }

    function gainPoints(points: number) {
        let element = state.tag.codename.html;
        if (!element) return;

        animatePoints(element, points, gainPreset.random);
    }

    return As(state, {
        layout,
        syncWithAppState,
        beforeAliasEdit,
        setAlias,
        hello,
        congrats,
        gainPoints,
    }) satisfies CsUi;
}