import type { CsConfig, CsGroups } from './cs-dependencies'
import { assert, helpers, logger } from './cs-dependencies'

interface AProfile {
    codename: string;
    alias: string;
    profileId: string;
    helloIsHere: boolean;
}

interface CsProfile {
    get codename(): string;
    get alias(): string;
    get profileId(): string;
    get helloIsHere(): boolean;
    get activeProfiles(): AProfile[];
    get activeCount(): number;
    hello(): void;
    setAlias(alias: string): void;
    clearAlias(): void;
    setProfileAliases(alias: string, profileIds: string[]): void;
    clearProfileAliases(profileIds: string[]): void;
    plusMinus(): void;
    switchTo(index: 1 | 2): void;
    clearCache(): void;
}

export function makeProfile(groups: CsGroups, config: CsConfig): CsProfile {
    let log = logger.make("profile");

    let makeProfileId = 
        (codename: string) => `${codename}@${config.deviceId}`;

    let profiles = $state(loadProfiles());
    let ui = () => profiles[0];
    let selfProfileIds = config.codenames.map(makeProfileId);

    groups.set("self-student", selfProfileIds);

    function hello() {
        ui().helloIsHere = true;
    }

    function loadProfiles() {
        return config.codenames.map(codename => {
            let profileId = makeProfileId(codename);
            let alias = localStorage.getItem(profileId) || codename;
            log.info(_=>_({profileId, alias}));
            let helloIsHere = false;
            return {codename, alias, profileId, helloIsHere};
        });
    }

    function setAlias(alias: string) {
        ui().alias = alias;
        localStorage.setItem(ui().profileId, alias);
    }

    function clearAlias() {
        ui().alias = ui().codename;
        localStorage.removeItem(ui().profileId);
    }

    function setProfileAliases(alias: string, profileIds: string[]) {
        profileIds.forEach(id => {
            if (!id.endsWith(config.deviceId))
                return;

            if (id === ui().profileId) {
                setAlias(alias);
                return;
            }

            let profile = profiles.find(pro => id === pro.profileId);

            if (!profile) {
                log.warn(_=>_(`My devide ${id} but not my profile`));
                return;
            }

            localStorage.setItem(id, alias);
            profile.alias = alias;
        });
    }

    function clearProfileAliases(profileIds: string[]) {
        profileIds.forEach(id => {
            if (!id.endsWith(config.deviceId))
                return;
            localStorage.removeItem(id);
        });
    }

    function updateGroupOfActiveProfileIds() {
        let activeIds = activeProfiles().map(pro => pro.profileId);
        groups.replace("self-student", selfProfileIds, activeIds);
        log.info(_=>_(groups.get("self-student")));
    }

    let activeCount = 1;
    let plusMinusCount = 0;

    function plusMinus() {
        assert(() => profiles.length === 3);

        plusMinusCount = ++plusMinusCount % 4;
        log.info(_=>_({plusMinusCount}));

        switch (plusMinusCount) {
            case 0:
                activeCount = 1;
                break;
            case 1:
            case 3:
                activeCount = 2;
                break;
            case 2:
                activeCount = 3;
                break;
        }

        updateGroupOfActiveProfileIds();
    }

    function switchTo(index: 1 | 2) {
        assert(() => index < activeCount);

        [profiles[0], profiles[index]] = [profiles[index], profiles[0]];
        updateGroupOfActiveProfileIds();
    }

    function activeProfiles() {
        return $state
            .snapshot(profiles)
            .slice(0, activeCount);
    }

    function clearCache() {
        config.codenames.map(codename => {
            let profileId = makeProfileId(codename);
            localStorage.removeItem(profileId);
        });
    }

    return {
        get codename() { return ui().codename; },
        get alias() { return ui().alias; },
        get profileId() { return ui().profileId; },
        get helloIsHere() { return ui().helloIsHere; },
        get activeProfiles() { return activeProfiles(); },
        get activeCount() { return activeCount; },
        hello,
        setAlias,
        clearAlias,
        setProfileAliases,
        clearProfileAliases,
        plusMinus,
        switchTo,
        clearCache,
    } as const satisfies CsProfile;
}