<script lang="ts">
    import QrCode from '../../ui/QrCode.svelte'
    import Classroom from "./Classroom.svelte";

    import type { ClassroomInfo } from '../tch-dependencies'
    import { browser, logger, helpers, makeMain } from '../tch-dependencies'
  
    let appId = helpers.makeId(2, "tch.")
    logger.setAppId(appId);

    let log = logger.make("cockpit");

    let tch = makeMain(appId);

    let selected = $state(0);

    let info = $derived(tch.info);
    let ui = $derived(tch.classroomUi);

    function rowClick(i: number) {
        selected = i;
        tch.switchToClassroom(i);
    }

    async function pasteClick() {
        log.info(_=>_());
        let text = await browser.readFromClipboard();
        tch.all.pasteStudents(text);
    }

    $effect(() => tch.updateBrowserTitle());
</script>

{#snippet toolbar()}
    <div class="toolbar">
        <div class="btn" onclick={pasteClick}>Paste</div>
    </div>
{/snippet}

{#snippet single(info: ClassroomInfo, i: number)}
    <tr class="row" 
        class:selected-row={i === selected}
        onclick={() => rowClick(i)}
    >
        <td>{info.group}</td>
        <td><b>{info.classroom}</b></td>
        <td>{info.teacher}</td>
        <td>{info.school}</td>
    </tr>
{/snippet}

<div class="selector">
    <div class="table">
        <table class="table">
            <tbody>
                {#each tch.classrooms as info, i}
                    {@render single(info, i)}
                {/each}
            </tbody>
        </table>
    </div>
    <div class="panel qr-code">
        <QrCode classroom={info.classroom} size={160}/>
    </div>
</div>

{@render toolbar()}
<br>

<Classroom {ui}/>

<style>
    .selector {
        display: flex;
    }
    .table {
        flex: 0 0 70%;
    }
    .panel {
        flex: 1;
        background-color: white;
        z-index: 10;
    }
    .qr-code {
        transform-origin: top right;
        transition: transform 0.3s;
    }
    .qr-code:hover {
        transform: scale(2.0);
    }
    .row:hover {
        background-color: #f0f7ff;
    }
    .selected-row {
        background-color: #e3f1ff;
    }
    .selected-row:hover {
        background-color: #d6ebff;
    }
</style>
