<script lang="ts">
    import { SvelteMap } from "svelte/reactivity";
    import { fly, fade } from "svelte/transition";
    import { flip } from "svelte/animate";

    import { type Toast } from './toasts-box.svelte'

    interface Props {
        daisyUi: string;
        toasts: SvelteMap<number, Toast>;
    }

    let { daisyUi, toasts }: Props = $props();
</script>

<div class="toast absolute {daisyUi} z-50">
    <div class="flex flex-col gap-2">
        {#each toasts.values() as toast (toast.id)}
            <div 
                animate:flip={{ duration: 300 }}
                in:fade={{ duration: 300 }}
                out:fade={{ duration: 300 }}
                class="alert alert-{toast.severity} font-bold text-xl"
            >
                {toast.msg}
            </div>
        {/each}
    </div>
</div>
