<script lang="ts">
    import type { StudentUi } from '../tch-dependencies'
    import { theme } from '../tch-dependencies'

    interface Props {
        stu: StudentUi;
    }

    let m = (clr: string) => theme.map(clr)

    let { stu } : Props = $props();
    let { peers } = $derived(stu);

    let connected = $derived(peers.length > 0);
    let mobileIsHere = $derived(stu.model.mobileIsHere);
    let color = $derived(mobileIsHere ? "darkgreen" : "red");
    let bgColor = $derived(mobileIsHere ? m("bg-green-50") : m("bg-red-50"));
    let bgHover = $derived(mobileIsHere ? m("bg-green-100") : m("bg-red-100"));
    let icon = $derived(mobileIsHere ? "fa-mobile-screen" : "fa-display");
</script>

<div class="toolbar">
    <div class="item">
        {#if connected}
            <button type="button" title="" class="item-button">
                <i class="fa-solid {icon} {color}" 
                    style:color={color}
                    style:--bgColor={bgColor}
                    style:--bgHover={bgHover}
                >
                </i>
            </button>
        {/if}
    </div>        
</div>

<style>
    i {
        background-color: var(--bgColor);
    }
    i:hover {
        background-color: var(--bgHover);
