import { 
    logger, helpers, browser, makeAbly, config, makeGroups,
    makePresence, makeProfile, makeUi, makeProxyFactory,
    makeToasts,
    VERSION,
} from './cs-dependencies'

import type {
    CsUi, CsProtocol, CsProfile, CsToasts,
} from './cs-dependencies'


interface CsMain {
    get all(): CsMain;
    ui: CsUi;
    profile: CsProfile;
    toasts: CsToasts;

    hello(): void;
    yes(): void,
    no(): void,
    addProfile(): boolean;
    setAliasOnEdit(alias: string): void;
    clearAlias(): void;
    switchProfileTo(index: 1 | 2): void;
    tagClick(id: string, value: string): void;

    sendIAmHere(): void;
    trackTeachers(): void;
    updateBrowserTitle(): void;

    t2sSetProfileAlias(msg: CsProtocol["t2s-set-profile-alias"]): void;
    t2sClearProfileAlias(msg: CsProtocol["t2s-clear-profile-alias"]): void;
    t2sClearCache(msg: CsProtocol["t2s-clear-cache"]): void;
    t2sCongrats(msg: CsProtocol["t2s-congrats"]): void;
    t2sGainPoints(msg: CsProtocol["t2s-gain-points"]): void;
    t2sSetState(msg: CsProtocol["t2s-set-state"]): void;
}

export function makeMain(appId: string) {
    let log = logger.make("cs-main");

    log.info(_=>_({
        appId, 
        deviceId: config.deviceId,
        classroom: config.classroom,
        config
    }));

    let groups = makeGroups();
    let profile = makeProfile(groups, config);
    let ably = makeAbly(browser, {appId, ...config});
    let presence = makePresence(appId, config, profile, browser);
    let ui = makeUi(appId, profile, config);
    let toasts = makeToasts();

    let itsMyTarget = (profileId: string) => 
        groups.itsMyGroup("self-student", profileId);

    ably.subscribe(itsMyTarget,
        ["t2s-set-profile-alias", t2sSetProfileAlias],
        ["t2s-clear-profile-alias", t2sClearProfileAlias],
        ["t2s-clear-cache", t2sClearCache],
        ["t2s-congrats", t2sCongrats],
        ["t2s-gain-points", t2sGainPoints],
        ["t2s-set-state", t2sSetState],
    );

    function hello() {
        if (presence.helloIsHere)
            return;

        log.info(_=>_());

        browser.preventLockScreen();

        profile.hello();
        presence.hello(true);
        ui.hello();
    }

    let publishAnswer = function(value: string) {
        ably.publish("s2t-answer", {
            profileId: profile.profileId,
            value
        });
    }

    function yes() {
        log.info(_=>_());
        publishAnswer("yes");
    }

    function no() {
        log.info(_=>_());
        publishAnswer("no");
    }

    function addProfile(): boolean {
        log.info(_=>_());
        profile.plusMinus();
        return profile.activeCount > 1;
    }

    function setAliasOnEdit(alias: string) {
        log.info(_=>_(alias));

        ui.setAlias(alias);
        profile.setAlias(alias);
    }

    function clearAlias() {
        log.info(_=>_());
        profile.clearAlias();
    }

    function switchProfileTo(index: 1 | 2) {
        log.info(_=>_({index}));
        profile.switchTo(index);
    }

    function tagClick(id: string, value: string) {
        log.info(_=>_({id, value}));
        browser.copyToClipboard(value);
    }

    function sendIAmHere() {
        let iAmHere = presence.iAmHere;
        log.info(_=>_(iAmHere));
        ably.present(iAmHere);
    }

    function trackTeachers() {
        let teachers = ably.presence.teachers;
        let teacherIsHere = teachers.length > 0;
        
        ui.connected = teacherIsHere;
        let hostId = "???";

        if (teacherIsHere) {
            hostId = teachers[0].hostId.toString();
        }

        ui.tag.status.text = hostId;

        log.trace(_=>_({teacherIsHere, hostId}));
    }

    function updateBrowserTitle() {
        let domain = location.hostname;
        let classroom = config.classroom;
        let alias = profile.alias;
        let title = `${alias} ${classroom}@${domain} ${VERSION}`;
        browser.setPageTitle(title);
    }

    function t2sSetProfileAlias(msg: CsProtocol["t2s-set-profile-alias"]) {
        log.info(_=>_(msg));
        profile.setProfileAliases(msg.alias, msg.profileIds);
    }

    function t2sClearProfileAlias(msg: CsProtocol["t2s-clear-profile-alias"]) {
        log.info(_=>_(msg));
        profile.clearProfileAliases(msg.profileIds);
    }

    function t2sClearCache(msg: CsProtocol["t2s-clear-cache"]) {
        let itsMyDevice = msg.deviceIds.includes(config.deviceId);
        log.warn(_=>_({itsMyDevice, msg}));

        if (!itsMyDevice)
            return;

        config.clearLocals();
        location.reload();
    }

    function t2sCongrats(msg: CsProtocol["t2s-congrats"]) {
        log.info(_=>_(msg));
        toasts.push(msg.message);
        ui.congrats();
    }

    function t2sGainPoints(msg: CsProtocol["t2s-gain-points"]) {
        log.info(_=>_(msg));
        ui.gainPoints(msg.points);
    }

    function t2sSetState(msg: CsProtocol["t2s-set-state"]) {
        log.info(_=>_(msg));
    }

    let self = {
        get all() { return proxyToAll; },
        ui, profile,
        toasts,
        hello,
        yes,
        no,
        addProfile,
        setAliasOnEdit,
        clearAlias,
        switchProfileTo,
        tagClick,
        sendIAmHere,
        trackTeachers,
        updateBrowserTitle,
        t2sSetProfileAlias,
        t2sClearProfileAlias,
        t2sClearCache,
        t2sCongrats,
        t2sGainPoints,
        t2sSetState,
    } as const satisfies CsMain

    let proxies = makeProxyFactory(ably, () => profile.profileId, itsMyTarget);
    let proxyToAll: CsMain = proxies.make("cs", self);

    return self;
}
