import { browser } from './browser';
import { logger } from './logger.svelte'

interface Theme {
    map(color: string): string;
    map(color: string | undefined): string | undefined;
    resolve(color: string): Promise<string>;
}

export const theme = (() => {
    let log = logger.make("theme");

    let canvas = document.createElement("canvas");
    
    let context = canvas.getContext("2d", {
        willReadFrequently: true
    })!;

    let colors = new Map<string, string>();
    let styles = getComputedStyle(document.documentElement);

    let knownColors = [
        "transparent",
        "black",
        "white",
        "gray",
        "silver",
        "red",
        "darkred",
        "lightcoral",
        "salmon",
        "tomato",
        "orange",
        "gold",
        "yellow",
        "khaki",
        "olive",
        "green",
        "darkgreen",
        "lightgreen",
        "lime",
        "teal",
        "cyan",
        "aqua",
        "lightblue",
        "blue",
        "darkblue",
        "navy",
        "indigo",
        "violet",
        "purple",
        "magenta",
        "fuchsia",
        "pink",
        "hotpink",
        "brown",
        "beige",
        "ivory",
    ];

    let tailwind = document.createElement("div");
    tailwind.hidden = true;
    document.body.appendChild(tailwind);

    let darkTheme = window.matchMedia("(prefers-color-scheme: dark)").matches;
    log.info(_=>_({darkTheme}));

    function readCssStyles() {
        styles = getComputedStyle(document.documentElement);
    }

    function css2rgb(color: string) {
        context.clearRect(0, 0, 1, 1);

        context.fillStyle = color;
        context.fillRect(0, 0, 1, 1);

        let [red, green, blue, alpha] =
            context.getImageData(0, 0, 1, 1).data;

        let values = alpha === 255
            ? [red, green, blue]
            : [red, green, blue, alpha];

        return "#" + values
            .map(value => value.toString(16).padStart(2, "0"))
            .join("")!;
    }

    function itsRgbHex(color: string) {
        return color.startsWith("#");
    }

    function itsTailwind(color: string) {
        return color.startsWith("bg-") ||
               color.startsWith("text-") ||
               color.startsWith("border-") ||
               color.startsWith("fill-") ||
               color.startsWith("stroke-");
    }

    function itsKnown(color: string): boolean {
        let lowercase = color.toLowerCase();
        return !!knownColors.find(known => known === lowercase);
    }

    function tailwind2css(color: string) {
        let tailwind = color.replace(
            /^(bg|text|border|fill|stroke)-/,
            ""
        );

        let css = styles
            .getPropertyValue(`--color-${tailwind}`)
            .trim();

        return css;
    }

    function itsBlack(rgb: string) {
        return rgb.startsWith("#000000");
    }

    async function resolve(color: string) {
        let div = document.createElement("div");
        div.className = `hidden ${color}`;
        tailwind.appendChild(div);

        await browser.doneIf(() => {
            let css = getComputedStyle(div).backgroundColor;
            let rgb = css2rgb(css);
            return !itsBlack(rgb);
        });

        readCssStyles();
        tailwind.removeChild(div);

        log.info(_=>_(`${color} is resolved`));

        return map(color);
    }

    function map(color: string | undefined) {
        if (!color) return color;

        let mapped = colors.get(color);
        if (mapped) return mapped;

        if (itsRgbHex(color))
            return color;

        function set(key: string, value: string, css: string) {
            log.info(_=>_(`${key} --> ${value} (css='${css}')`));
            colors.set(key, value);
        }

        if (itsKnown(color)) {
            set(color, color, color);
            return color;
        }

        if (itsTailwind(color)) {
            let css = tailwind2css(color);
            let rgb = css2rgb(css);

            if (itsBlack(rgb)) {
                log.warn(_=>_(`failed to resolve ${color}`));
                return "tranparent";
            }

            set(color, rgb, css);
            return rgb;
        }

        colors.set(color, color);
        return color;
    }

    return {
        map,
        resolve,
    } as Theme;
})();
