import type {
    ClassroomUi,
} from './tch-dependencies'

import { 
    logger, helpers, browser, theme, makeAbly, config, makeProxyFactory,
    makeCsListener, makeClassroom, makeClassroomUi, makeToasts,
    VERSION,
} from './tch-dependencies'

export type ClassroomInfo = {
    group: string;
    classroom: string;
    teacher: string;
    school: string;
}


interface CsCockpit {
    get appId(): string;
    get all(): CsCockpit;
    get classrooms(): ClassroomInfo[];
    get info(): ClassroomInfo;
    get classroomUi(): ClassroomUi;
    switchToClassroom(indx: number): void;
    pasteStudents(text: string): void;
    updateBrowserTitle(): void;
}

let classrooms: ClassroomInfo[] = $state([{
    group: "1-18",
    classroom: "112233",
    teacher: "גושה",
    school: "Gebemot"
}, {
    group: "3-19",
    classroom: "223344",
    teacher: "מריה",
    school: "Gebemot"
}, {
    group: "יא-7",
    classroom: "334455",
    teacher: "גושה",
    school: "עתידים"

}, {
    group: "י-7",
    classroom: "445566",
    teacher: "גושה",
    school: "עתידים"
}]);


export function makeMain(appId: string) {
    let log = logger.make("tch-main");

    let profileId = `${config.codenames[0]}@${config.deviceId}`;

    log.info(_=>_({
        appId,
        deviceId: config.deviceId,
        profileId,
        config,
    }));

    let ably = makeAbly(browser, {appId, ...config});
    let toasts = makeToasts();
    let classroom = makeClassroom(appId, config.classroom, browser, ably, toasts);
    let ui = makeClassroomUi(ably, toasts, classroom);

    let csListener = makeCsListener();

    let proxies = makeProxyFactory(ably, () => profileId, () => true);
    proxies.make("cs", csListener);

    ably.subscribe(() => true,
        ["s2t-answer", classroom.s2tAnswer],
    );

    let current = $state(0);

    function switchToClassroom(indx: number) {
        current = indx;
        log.info(_=>_(`switch to classroom: '${classrooms[indx].classroom}'`));
        classroom.selected();
    }

    function pasteStudents(text: string) {
        log.info(_=>_(text));
        classroom.pasteStudents(text);
    }

    function updateBrowserTitle() {
        let domain = location.hostname;
        let title = `teacher ${classroom.id}@${domain} ${VERSION}`;
        browser.setPageTitle(title);
    }

    let self = {
        get appId() { return appId; },
        get all() { return proxyToAll; },
        get classrooms() { return classrooms; },
        get info() { return classrooms[current]; },
        get classroomUi() { return ui; },
        switchToClassroom,
        pasteStudents,
        updateBrowserTitle,
    } as const satisfies CsCockpit;

    let proxyToAll: CsCockpit = proxies.make("tch", self);

    return self;
}
