import type { CsToasts } from '../tch-dependencies'
import { assert, logger } from '../tch-dependencies'

interface PasteParser {
    parseStudents(text: string): string[][];
}

export function makePasteParser(toasts: CsToasts) {
    let log = logger.make("paste-parser");

    function splitToCells(text: string): string[][] {
        return text
            .replace(/\r\n?/g, "\n")
            .split("\n")
            .map(line => line.split("\t").map(cell => cell.trim()))
            .filter(row => row.some(cell => cell.length > 0));
    }

    function parseStudents(text: string): string[][] {
        function *splitToCells(lnNum: number, text: string) {
            let cells = text
                .split("\t")
                .map(cell => cell.trim());

            yield* cells;
        }

        function lineIsEmpty(cells: string[]) {
            return cells.every(cell => cell.length === 0);
        }

        function *splitToLines(text: string) {
            let lnNum = 0;

            let lines = text
                .replace(/\r\n?/g, "\n")
                .split("\n");

            for (let line of lines) {
                lnNum++;

                let cells = [...splitToCells(lnNum, line)];

                if (lineIsEmpty(cells))
                    continue;

                assert(() => cells.length > 0);

                if (cells[0].length === 0)
                    throw new Error(`Line ${lnNum}: first column should not be empty`);

                if (cells[0].length > 0)
                    yield cells;
            }
        }

        return [...splitToLines(text)];
    }

    return {
        parseStudents,
    } satisfies PasteParser;
}
